DO $$
DECLARE
  table_name TEXT;
BEGIN
  FOREACH table_name IN ARRAY ARRAY[
    'company_settings', 'roles', 'regions', 'territories', 'teams', 'branches', 'warehouses',
    'stores', 'inventory_movements', 'alerts', 'deliveries', 'order_approvals', 'store_requests',
    'schedules', 'location_logs', 'location_alerts', 'field_activities', 'sales_activities',
    'daily_summaries', 'task_reminders', 'reminder_delivery_logs', 'employee_idle_sessions'
  ] LOOP
    EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', table_name);
    EXECUTE format('GRANT ALL ON TABLE public.%I TO service_role', table_name);
  END LOOP;
END;
$$;

