-- 015_uuid_replay_repair.sql
DO $install_015$
BEGIN
  IF EXISTS (SELECT 1 FROM private.edgewforce_migrations WHERE version = '015' AND checksum <> '63c35b24c7ad501a09635ed3b2096166fb582bcfd6fbe4b14b88ecff2f578f38') THEN
    RAISE EXCEPTION 'Migration 015 was edited after installation. Use a new numbered migration; no changes were committed.';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM private.edgewforce_migrations WHERE version = '015') THEN
    IF (15 <= (SELECT adopt_through FROM edgewforce_install_state))
       OR ('015' = '006' AND (SELECT preserve_existing_staff FROM edgewforce_install_state)) THEN
      INSERT INTO private.edgewforce_migrations(version, name, checksum, source)
      VALUES ('015', '015_uuid_replay_repair.sql', '63c35b24c7ad501a09635ed3b2096166fb582bcfd6fbe4b14b88ecff2f578f38', 'adopted');
    ELSE
      EXECUTE $migration_015$
-- Repair installations that used the earlier migration bundle. Never reseed staff.


DO $$
DECLARE
  col RECORD;
BEGIN
  -- Older 011/012 files retained NOT NULL on retired numeric references.
  FOR col IN
    SELECT old.table_name, old.column_name
    FROM information_schema.columns old
    JOIN information_schema.columns current_col
      ON current_col.table_schema = old.table_schema
      AND current_col.table_name = old.table_name
      AND current_col.column_name = substring(old.column_name FROM 8)
      AND current_col.data_type = 'uuid'
    WHERE old.table_schema = 'public' AND old.column_name LIKE 'legacy\_%' ESCAPE '\'
      AND old.is_nullable = 'NO'
  LOOP
    EXECUTE format('ALTER TABLE public.%I ALTER COLUMN %I DROP NOT NULL', col.table_name, col.column_name);
  END LOOP;
END;
$$;

