    END IF;
  END IF;
END;
$install_015$;

-- 016_runtime_user_references_uuid.sql
DO $install_016$
BEGIN
  IF EXISTS (SELECT 1 FROM private.edgewforce_migrations WHERE version = '016' AND checksum <> '1d19139aa085711e2ecf8eafe33a27ea35bc93c8521601dc53642d1248d38f4e') THEN
    RAISE EXCEPTION 'Migration 016 was edited after installation. Use a new numbered migration; no changes were committed.';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM private.edgewforce_migrations WHERE version = '016') THEN
    IF (16 <= (SELECT adopt_through FROM edgewforce_install_state))
       OR ('016' = '006' AND (SELECT preserve_existing_staff FROM edgewforce_install_state)) THEN
      INSERT INTO private.edgewforce_migrations(version, name, checksum, source)
      VALUES ('016', '016_runtime_user_references_uuid.sql', '1d19139aa085711e2ecf8eafe33a27ea35bc93c8521601dc53642d1248d38f4e', 'adopted');
    ELSE
      EXECUTE $migration_016$
-- Convert the user references introduced after migration 012. Keep numeric row
-- IDs and the original values in legacy_* columns for compatibility and audit.


DO $migration$
DECLARE
  ref RECORD;
  current_type TEXT;
  missing_count BIGINT;
  fk_name TEXT;
BEGIN
  FOR ref IN SELECT * FROM (VALUES
    ('inventory_movements', 'recorded_by'),
    ('orders', 'approved_by'),
    ('order_approvals', 'approver_id'),
    ('tasks', 'acknowledged_by'),
    ('tasks', 'completed_by')
  ) AS refs(table_name, column_name)
  LOOP
    SELECT data_type INTO current_type
    FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = ref.table_name
      AND column_name = ref.column_name;

    IF current_type NOT IN ('bigint', 'integer', 'uuid') OR current_type IS NULL THEN
      RAISE EXCEPTION 'Unexpected identity type %.%: %',
        ref.table_name, ref.column_name, current_type;
    END IF;

    IF current_type <> 'uuid' THEN
      EXECUTE format('ALTER TABLE public.%I ADD COLUMN %I UUID',
        ref.table_name, ref.column_name || '_uuid');
      EXECUTE format(
        'UPDATE public.%I AS target SET %I = source.uuid
         FROM public.users AS source WHERE target.%I = source.id',
        ref.table_name, ref.column_name || '_uuid', ref.column_name
      );
      EXECUTE format(
        'SELECT count(*) FROM public.%I WHERE %I IS NOT NULL AND %I IS NULL',
        ref.table_name, ref.column_name, ref.column_name || '_uuid'
      ) INTO missing_count;
      IF missing_count <> 0 THEN
        RAISE EXCEPTION 'Cannot map %.% to users.uuid: % row(s). No changes were committed.',
          ref.table_name, ref.column_name, missing_count;
      END IF;
      EXECUTE format('ALTER TABLE public.%I RENAME COLUMN %I TO %I',
        ref.table_name, ref.column_name, 'legacy_' || ref.column_name);
      EXECUTE format('ALTER TABLE public.%I RENAME COLUMN %I TO %I',
        ref.table_name, ref.column_name || '_uuid', ref.column_name);
    END IF;

    fk_name := ref.table_name || '_' || ref.column_name || '_users_uuid_fkey';
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = fk_name
      AND conrelid = format('public.%I', ref.table_name)::regclass) THEN
      EXECUTE format(
        'ALTER TABLE public.%I ADD CONSTRAINT %I FOREIGN KEY (%I)
         REFERENCES public.users(uuid) ON DELETE SET NULL NOT VALID',
        ref.table_name, fk_name, ref.column_name
      );
    END IF;
    EXECUTE format('ALTER TABLE public.%I VALIDATE CONSTRAINT %I', ref.table_name, fk_name);
    EXECUTE format('CREATE INDEX IF NOT EXISTS %I ON public.%I (%I)',
      'idx_uuidref_' || ref.table_name || '_' || ref.column_name,
      ref.table_name, ref.column_name);
  END LOOP;
END;
$migration$;



$migration_016$;
      INSERT INTO private.edgewforce_migrations(version, name, checksum, source)
      VALUES ('016', '016_runtime_user_references_uuid.sql', '1d19139aa085711e2ecf8eafe33a27ea35bc93c8521601dc53642d1248d38f4e', 'applied');
    END IF;
  END IF;
END;
$install_016$;

-- Validate the identity contract before committing, including adopted databases.
DO $verify$
DECLARE
  ref RECORD;
  actual_type TEXT;
  orphan_count BIGINT;
BEGIN
  FOR ref IN SELECT * FROM (VALUES
    ('employees', 'user_id', 'users'),
    ('employees', 'reporting_manager_id', 'employees'),
    ('employees', 'supervisor_id', 'employees'),
    ('customers', 'registered_by', 'employees'),
    ('customers', 'assigned_agent_id', 'employees'),
    ('customers', 'assigned_supervisor_id', 'employees'),
    ('orders', 'sales_agent_id', 'employees'),
    ('collections', 'agent_id', 'employees'),
    ('visits', 'agent_id', 'employees'),
    ('competitor_intel', 'agent_id', 'employees'),
    ('location_tracking', 'agent_id', 'employees'),
    ('visit_reports', 'agent_id', 'employees'),
    ('attendance', 'employee_id', 'employees'),
    ('leave_balances', 'employee_id', 'employees'),
    ('leave_requests', 'employee_id', 'employees'),
    ('leave_requests', 'reviewed_by', 'employees'),
    ('payslips', 'employee_id', 'employees'),
    ('settlements', 'agent_id', 'employees'),
    ('sos', 'agent_id', 'employees'),
    ('idle_alerts', 'employee_id', 'employees'),
    ('face_events', 'employee_id', 'employees'),
    ('okrs', 'employee_id', 'employees'),
    ('tasks', 'assigned_to', 'employees'),
    ('schedules', 'employee_id', 'employees'),
    ('schedules', 'assigned_agent_id', 'employees'),
    ('store_requests', 'agent_id', 'employees'),
    ('location_alerts', 'agent_id', 'employees'),
    ('employee_idle_sessions', 'employee_id', 'employees'),
    ('push_subscriptions', 'employee_id', 'employees'),
    ('notifications', 'employee_id', 'employees'),
    ('inventory_transactions', 'created_by', 'users'),
    ('payslips', 'generated_by', 'users'),
    ('settlements', 'reviewed_by', 'users'),
    ('sos', 'acknowledged_by', 'users'),
    ('sos', 'resolved_by', 'users'),
    ('idle_alerts', 'reviewed_by', 'users'),
    ('tasks', 'assigned_by', 'users'),
    ('task_comments', 'author_id', 'users'),
    ('announcements', 'created_by', 'users'),
    ('store_requests', 'reviewed_by', 'users'),
    ('location_alerts', 'acknowledged_by', 'users'),
    ('location_alerts', 'resolved_by', 'users'),
    ('employee_idle_sessions', 'reviewed_by', 'users'),
    ('audit_logs', 'actor_id', 'users'),
    ('file_uploads', 'uploaded_by', 'users'),
    ('file_attachments', 'uploaded_by', 'users'),
    ('ai_conversations', 'user_id', 'users'),
    ('employee_location_assignments', 'employee_id', 'employees'),
    ('location_assignment_history', 'employee_id', 'employees'),
    ('task_reminders', 'employee_id', 'employees'),
    ('task_reminders', 'user_id', 'users'),
    ('inventory_movements', 'recorded_by', 'users'),
    ('orders', 'approved_by', 'users'),
    ('order_approvals', 'approver_id', 'users'),
    ('tasks', 'acknowledged_by', 'users'),
    ('tasks', 'completed_by', 'users')
  ) AS refs(table_name, column_name, parent_table)
  LOOP
    SELECT data_type INTO actual_type FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = ref.table_name AND column_name = ref.column_name;
    IF actual_type IS NULL THEN CONTINUE; END IF;
    IF actual_type <> 'uuid' THEN
      RAISE EXCEPTION 'Identity contract mismatch: %.% must be uuid, found %. No changes were committed.', ref.table_name, ref.column_name, actual_type;
    END IF;
    EXECUTE format('SELECT count(*) FROM public.%I child LEFT JOIN public.%I parent ON child.%I = parent.uuid WHERE child.%I IS NOT NULL AND parent.uuid IS NULL', ref.table_name, ref.parent_table, ref.column_name, ref.column_name) INTO orphan_count;
    IF orphan_count <> 0 THEN
      RAISE EXCEPTION 'Unmapped identities in %.%: % row(s). No changes were committed; data must be reconciled, not cast.', ref.table_name, ref.column_name, orphan_count;
    END IF;
  END LOOP;
END;
$verify$;
NOTIFY pgrst, 'reload schema';
COMMIT;
SELECT 'EdgeWForce database ready' AS status,
       (SELECT count(*) FROM public.employees) AS staff_count,
       (SELECT count(*) FROM private.edgewforce_migrations) AS migrations_recorded;
